#include <iostream>

int main()
{
    int s{};
    if (!(std::cin >> s)) return 0;

    int hours{ s / 3600 };
    int leftover{ s % 3600 };
    int minutes{ leftover / 60 };
    int seconds{ leftover % 60 };

    std::cout << hours << ':';
    if (minutes < 10) std::cout << '0';
    std::cout << minutes << ':';
    if (seconds < 10) std::cout << '0';
    std::cout << seconds << "\n";

    return 0;
}
